args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-bulk-omics-reproduction/golgiphagy');PD<-file.path(P,'results/plot_data');stem<-'golgiphagy_proteome_composite_20261029';library(dplyr);library(tidyr)
h<-read.csv(file.path(W,'HeLa-18h_EBSS.csv'));k<-read.csv(file.path(W,'HEK293_12h_EBSS.csv'));organ<-read.csv(file.path(W,'ss_organelle_list2_wh_annotation_cytoAddedBasedGO.csv'));org<-pivot_longer(organ,everything(),names_to='Compartment_ss',values_to='Gene.Symbol')%>%filter(!is.na(Gene.Symbol),Gene.Symbol!='')%>%distinct()%>%filter(Compartment_ss%in%c('Nucleus','Endosome','Golgi','ER','Plasma.Membrane','Mitochondria','Lysosome','Peroxisome','Cytosol'))
hloc<-left_join(h%>%filter(log2FC_1_control_EBSS.0_control > -3.5),org,by='Gene.Symbol',relationship='many-to-many')%>%mutate(locale=Compartment_ss);b<-bind_rows(hloc,mutate(hloc,locale='Total'))%>%select(Gene.Symbol,Reference,locale,log2FC_1_control_EBSS.0_control,log2FC_3_ATG7.KO_EBSS.2_ATG7.KO)%>%pivot_longer(cols=4:5,names_to='CellLine',values_to='Value')%>%mutate(CellLine=ifelse(grepl('ATG7',CellLine),'ATG7 KO','WT'))%>%filter(locale%in%c('Total','Golgi','ER'))
focus<-function(x,cell){x$source_row<-seq_len(nrow(x));x%>%mutate(cell=cell,x=log2FC_1_control_EBSS.0_control,y=log2FC_3_ATG7.KO_EBSS.2_ATG7.KO-log2FC_1_control_EBSS.0_control,focus_quad=ifelse(y>0&x<0,'focus','other'),priority=ifelse(focus_quad=='focus',pmin(abs(x),abs(y)),0))%>%filter(x> -3.5)}
c<-bind_rows(focus(h,'HeLa'),focus(k,'HEK293'))
for(n in c('b','c'))write.csv(get(n),file.path(PD,paste0(stem,'_',n,'.csv')),row.names=FALSE,na='')
jsonlite::write_json(list(status='PASS',b_rows=nrow(b),scatter_rows=nrow(c),b_plot_within_source_limits=sum(b$Value>=-1.5&b$Value<=1.5,na.rm=TRUE),author_join_multiplicity_retained=TRUE,statistics_required=FALSE,simulation=FALSE),file.path(W,'input-qc.json'),auto_unbox=TRUE,pretty=TRUE)
